/* Synthetic semantic evaluation; no corporate source. */
data mart.t01_result(keep=id miss low truth row_sum ordinary);
set source.events;
miss=missing(x);
if x<0 then low=1; else low=0;
if x then truth=1; else truth=0;
row_sum=sum(x,y);
ordinary=x+y;
run;

/* Synthetic semantic evaluation; no corporate source. */
data mart.t02_result(keep=id miss equal_code marker);
length marker $30;
set source.events;
miss=missing(code);
if code='ABC' then equal_code=1; else equal_code=0;
marker='run; quit; proc sql;';
run;

/* Synthetic semantic evaluation; no corporate source. */
proc sort data=source.events out=work.hi;
by k descending score seq;
run;
data mart.t03_top;
set work.hi;
by k descending score seq;
if first.k;
run;
proc sort data=source.events out=work.lo;
by k score seq;
run;
data mart.t03_bottom;
set work.lo;
by k score seq;
if first.k;
run;

/* Synthetic semantic evaluation; no corporate source. */
proc sort data=source.lefts out=work.l;
by k sensor id;
run;
proc sort data=source.rights out=work.r;
by k sensor;
run;
data mart.t04_result(keep=id amount bias adjusted);
merge work.l(in=a) work.r(in=b);
by k sensor;
if a;
adjusted=sum(amount,bias);
run;

/* Synthetic semantic evaluation; no corporate source. */
proc sort data=source.lefts out=work.l;
by k lseq;
run;
proc sort data=source.rights out=work.r;
by k rseq;
run;
data mart.t05_result;
merge work.l(in=a) work.r(in=b);
by k;
if a;
keep k lseq lvalue rseq rvalue;
run;

/* Synthetic semantic evaluation; no corporate source. */
proc sort data=source.lefts out=work.l;
by k id;
run;
proc sort data=source.rights out=work.r;
by k rseq;
run;
data mart.t06_result;
merge work.l(in=a) work.r(in=b);
by k;
if a;
keep k id age rvalue;
run;

/* Synthetic semantic evaluation; no corporate source. */
proc sort data=source.events out=work.ordered;
by g seq;
run;
data mart.t07_result(keep=id g seq total);
set work.ordered;
by g seq;
if first.g then total=0;
total+amount;
run;

/* Synthetic semantic evaluation; no corporate source. */
proc sort data=source.events out=work.ordered;
by seq;
run;
data mart.t08_result(keep=id prev);
set work.ordered;
if active=1 then prev=lag(amount);
else prev=.;
run;

/* Synthetic semantic evaluation; no corporate source. */
data mart.t09_result(keep=id x y);
set source.events;
where x>=0;
x=x+1;
if x>=1;
if x<3 then y=10;
if y=10 then y=y+x;
run;

/* Synthetic semantic evaluation; no corporate source. */
%let start='28FEB2024:00:00:00'dt;
%let finish='01APR2024:00:00:00'dt;
%macro summarize(active_flag=1);
proc sql;
create table mart.t10_result as
select g,intnx('month',datepart(observed_at),0,'b') as month format=yymmdd10.,
count(*) as n,sum(amount) as total
from source.events
where active=&active_flag and observed_at>=&start and observed_at<&finish
group by g,calculated month;
quit;
%mend;
%summarize(active_flag=1);

/* Synthetic semantic evaluation; no corporate source. */
data mart.t11_result;
length code $5 short $3;
set source.events;
if id<0 or id>99999 then delete;
code=put(id,z5.);
short='ABCDEF';
run;

/* Synthetic semantic evaluation; no corporate source. */
data mart.t12_result(drop=old);
set source.firsts(rename=(x=old)) source.seconds(rename=(x=old));
value=sum(old,1);
run;

/* Synthetic semantic evaluation; no corporate source. */
data mart.n01_result(keep=id flag);
set source.events;
if x=.A then flag=1; else flag=0;
run;

/* Synthetic semantic evaluation; no corporate source. */
proc sort data=source.events out=mart.n02_result nodupkey equals;
by k;
run;

%let floor=0; %macro clean; data work.cleaned work.rejected; set source.sales; if missing(customer_id) or missing(amount) or amount<&floor then output work.rejected; else output work.cleaned; run; %mend; %clean;
proc sql; create table work.enriched as select a.id,a.customer_id,a.g,a.observed_at,a.amount,b.segment from work.cleaned a left join source.customers b on a.customer_id=b.customer_id; quit;
%macro aggregate; proc sql; create table mart.flow_monthly as select intnx('month',datepart(observed_at),0,'b') as month format=yymmdd10.,segment,count(*) as n,sum(amount) as total from work.enriched group by calculated month,segment; quit; %mend; %aggregate;
data mart.flow_flags; set work.enriched; if amount>=100 then band='high'; else band='low'; keep id customer_id segment band; run;
